// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }

    function testFuzz_property(uint256 depositValue, uint256 amount, address actor) public {
        vm.assume(depositValue <= VALUE_CAP);
        // Keep the domain admissible: small-enough deposit, amount strictly below it,
        // and a plain recipient that accepts ETH transfers (not c itself).
        depositValue = bound(depositValue, 1, 1e18);
        amount = bound(amount, 0, depositValue - 1);
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));

        // Actor deposits depositValue into c.
        vm.deal(actor, depositValue);
        vm.prank(actor);
        c.deposit{value: depositValue}();

        // Actor withdraws only `amount` wei.
        vm.prank(actor);
        try c.withdraw(amount) {
            // RULE: a successful partial withdraw reduces the contract's ETH
            // balance by exactly `amount` wei.
            assertTrue(address(c).balance == depositValue - amount);
        } catch {
            // If the withdraw reverts, state must be untouched (contract keeps deposit).
            assertTrue(address(c).balance == depositValue);
        }
    }
}
